#![allow(unused)]
use verus::prelude::*;

/// Returns `true` if the character vector `v` starts with the prefix `p`.
/// An empty prefix always matches. If `p.len() > v.len()`, returns `false`.
#[verifier::pure] // so we can call it in specs
#[requires(true)]
#[ensures(
    // result iff p is a prefix of v
    result
    == (p.len() <= v.len()
        && forall |i: usize|
              i < p.len()
              ==> v.view()[i] == p.view()[i])
)]
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // Slice::starts_with on &[T] does exactly what we need.
    v.len() >= p.len() && v.as_slice().starts_with(p.as_slice())
}

/// Filters the input list of character vectors, keeping only those
/// that start with the given prefix `p`. The relative order is preserved.
#[requires(true)]
#[ensures(
    // The result viewed as a sequence is exactly
    // the original xs (from before the call) filtered
    // by the predicate has_prefix(_, &p).
    result.view()
    ==
    old(xs).view().filter(|w: &Vec<char>| has_prefix(w, &p))
)]
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
      .filter(|v| has_prefix(v, &p))
      .collect()
}

fn main() {
    // Example usage:
    let words = vec![
        vec!['a', 'p', 'p', 'l', 'e'],
        vec!['a', 'p', 'r', 'i', 'c', 'o', 't'],
        vec!['b', 'a', 'n', 'a', 'n', 'a'],
    ];
    let prefix = vec!['a', 'p'];
    let filtered = filter_by_prefix(words, prefix);
    // filtered == [vec!['a','p','p','l','e'], vec!['a','p','r','i','c','o','t']]
    println!("{:?}", filtered);
}